import java.util.Scanner;
class InsSort {
    int arr[];
    int size;
    InsSort(int s) { size = s; arr = new int[size]; }
    void getArray() {
        Scanner sc = new Scanner(System.in);
        for (int i = 0; i < size; i++) arr[i] = sc.nextInt();
    }
    void insertionSort() {
        for (int i = 1; i < size; i++) {
            int key = arr[i], j = i - 1;
            while (j >= 0 && arr[j] < key) { arr[j+1] = arr[j]; j--; }
            arr[j+1] = key;
        }
    }
    double find() {
        int sum = 0, cnt = 0;
        for (int x : arr) { if (x % 2 != 0) { sum += x; cnt++; } }
        return cnt == 0 ? 0.0 : (double)sum / cnt;
    }
    void display() {
        insertionSort();
        System.out.print("Sorted (desc): ");
        for (int x : arr) System.out.print(x + " ");
        System.out.println("\nAverage of odd numbers: " + find());
    }
    public static void main(String[] args) {
        InsSort obj = new InsSort(5);
        obj.getArray();
        obj.display();
    }
}

