import java.util.Scanner;
class CartonPacking {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter number of boxes N: ");
        int N = sc.nextInt();
        if (N <= 0 || N > 1000) {
            System.out.println("INVALID INPUT");
            return;
        }
        int[] sizes = {48, 24, 12, 6};
        int totalCartons = 0;
        int remaining = N;
        for (int s : sizes) {
            if (remaining >= s) {
                int cartons = remaining / s;
                int packed = cartons * s;
                remaining -= packed;
                totalCartons += cartons;
                System.out.println(s + " x " + cartons + " = " + packed);
            }
        }
        if (remaining > 0) {
            System.out.println("Remaining boxes " + remaining + " x 1 = " + remaining);
            totalCartons++;
        }
        System.out.println("Total number of boxes = " + N);
        System.out.println("Total number of cartons = " + totalCartons);
    }
}

