public class Perfect {
    int sumFactors(int n, int i) {
        if (i > n/2) return 0;
        if (n % i == 0)
            return i + sumFactors(n, i+1);
        else
            return sumFactors(n, i+1);
    }
    void checkPerfect(int n) {
        int sum = sumFactors(n, 1);
        if (sum == n)
            System.out.println(n + " is a perfect number");
    }
