class Register {
    int[] stk;
    int top;
    int maxSize;
    Register(int size) {
        maxSize = size;
        stk = new int[maxSize];
        top = -1;
    }
    boolean isEmpty() { return top == -1; }
    boolean isFull() { return top == maxSize-1; }
    void push(int val) {
        if (isFull()) System.out.println("Stack Overflow");
        else stk[++top] = val;
    }
    int pop() {
        if (isEmpty()) { System.out.println("Stack Underflow"); return -1; }
        return stk[top--];
    }
}

