class DayToDate {
    static String[] months = {"JANUARY","FEBRUARY","MARCH","APRIL","MAY","JUNE",
                               "JULY","AUGUST","SEPTEMBER","OCTOBER","NOVEMBER","DECEMBER"};
    static boolean isLeap(int yr) {
        return (yr % 400 == 0) || (yr % 4 == 0 && yr % 100 != 0);
    }
    static int[] toDate(int dayNo, int yr) {
        int[] d = {31, isLeap(yr)?29:28, 31,30,31,30,31,31,30,31,30,31};
        int m = 0;
        while (dayNo > d[m]) { dayNo -= d[m]; m++; }
        return new int[]{dayNo, m+1, yr};
    }
    static String suffix(int d) {
        if (d==1||d==21||d==31) return "ST";
        if (d==2||d==22) return "ND";
        if (d==3||d==23) return "RD";
        return "TH";
    }
    static void printDate(int[] dt) {
        System.out.println("DATE: " + dt[0] + " " + suffix(dt[0]) + " " + months[dt[1]-1] + ", " + dt[2]);
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("DAY NUMBER: "); int dayNo = sc.nextInt();
        System.out.print("YEAR: "); int yr = sc.nextInt();
        System.out.print("DATE AFTER (N DAYS): "); int n = sc.nextInt();
        int maxDays = isLeap(yr) ? 366 : 365;
        if (dayNo < 1 || dayNo > maxDays) {
            System.out.println("DAY NUMBER OUT OF RANGE."); return;
        }
        if (n < 1 || n > 100) {
            System.out.println("DATE AFTER (N DAYS) OUT OF RANGE."); return;
        }
        int[] date = toDate(dayNo, yr);
        printDate(date);
        int newDay = dayNo + n;
        int newYr = yr;
        if (newDay > maxDays) { newDay -= maxDays; newYr++; }
        int[] future = toDate(newDay, newYr);
        int[] f = future;
        System.out.println("DATE AFTER " + n + " DAYS: " + f[0] + " " + suffix(f[0]) + " " + months[f[1]-1] + ", " + f[2]);
    }
}

