class PalSentence {
    static boolean isPalin(String s) {
        int l = 0, r = s.length()-1;
        while (l < r) { if (s.charAt(l)!=s.charAt(r)) return false; l++; r--; }
        return true;
    }
    static String makePalin(String s) {
        if (isPalin(s)) return s;
        String rev = new StringBuilder(s).reverse().toString();
        // suffix = rev excluding first char, then skip chars equal to s's last char
        char lastCh = s.charAt(s.length()-1);
        int start = 1; // skip first char of rev (= last char of s)
        // skip additional duplicate chars at junction
        while (start < rev.length() && rev.charAt(start) == lastCh) start++;
        return s + rev.substring(start);
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter sentence: ");
        String sentence = sc.nextLine().trim();
        char last = sentence.charAt(sentence.length()-1);
        if (last != '.' && last != '?' && last != '!') {
            System.out.println("INVALID INPUT"); return;
        }
        System.out.println(sentence);
        String body = sentence.substring(0, sentence.length()-1);
        String[] words = body.split(" ");
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            if (i > 0) result.append(" ");
            result.append(makePalin(words[i]));
        }
        System.out.println(result.toString());
    }
}

