import java.util.Scanner;
public class BinSearch {
    int[] arr;
    int n;

    BinSearch(int nn) {
        n = nn;
        arr = new int[n];
    }

    void fillarray() {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter " + n + " elements:");
        for (int i = 0; i < n; i++)
            arr[i] = sc.nextInt();
    }

    void sort() {
        // Bubble sort
        for (int i = 0; i < n-1; i++) {
            for (int j = 0; j < n-i-1; j++) {
                if (arr[j] > arr[j+1]) {
                    int temp = arr[j];
                    arr[j] = arr[j+1];
                    arr[j+1] = temp;
                }
            }
        }
    }

    int bin_search(int l, int u, int v) {
        if (l > u) return -1; // not found
        int mid = (l + u) / 2;
        if (arr[mid] == v) return mid;
        else if (arr[mid] > v) return bin_search(l, mid-1, v);
        else return bin_search(mid+1, u, v);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter size: ");
        int size = sc.nextInt();
        BinSearch obj = new BinSearch(size);
        obj.fillarray();
        obj.sort();
        System.out.print("Enter value to search: ");
        int val = sc.nextInt();
        int pos = obj.bin_search(0, size-1, val);
        if (pos == -1)
            System.out.println(val + " not found");
        else
            System.out.println(val + " found at index " + pos);
    }
}

