        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a word in UPPERCASE: ");
        wrd = sc.next().toUpperCase();
        len = wrd.length();
    }

    void mix_word(Mix P, Mix Q) {
        // Mix characters of P and Q alternately
        StringBuilder result = new StringBuilder();
        int minLen = Math.min(P.len, Q.len);

        // Interleave common length
        for (int i = 0; i < minLen; i++) {
            result.append(P.wrd.charAt(i));
            result.append(Q.wrd.charAt(i));
        }

        // Append remaining characters of the longer word
        if (P.len > Q.len)
            result.append(P.wrd.substring(minLen));
        else if (Q.len > P.len)
            result.append(Q.wrd.substring(minLen));

        wrd = result.toString();
        len = wrd.length();
    }

    void display() {
        System.out.println("Mixed word: " + wrd);
    }

