Algorithm:
1. Accept m and n; if m >= n, print INVALID INPUT and stop.
2. For each number i from m to n:
   a. Check if i is prime (only factors are 1 and i).
   b. Find reverse of i; check if i is an Adam number (rev(i*i) == rev(i)*rev(i)).
   c. If both prime and Adam, print i and increment count.
3. Print FREQUENCY.

Java Program:
import java.util.Scanner;
public class PrimeAdam {

    static int reverse(int n) {
        int rev = 0;
        while (n > 0) {
            rev = rev * 10 + n % 10;
            n /= 10;
        }
        return rev;
    }

    static boolean isPrime(int n) {
        if (n < 2) return false;
        for (int i = 2; i <= Math.sqrt(n); i++)
            if (n % i == 0) return false;
        return true;
    }

    static boolean isAdam(int n) {
        int revN = reverse(n);
        long sq = (long) n * n;
        long sqRev = (long) revN * revN;
        return reverse((int) sq) == (int) sqRev;
        // Alternatively: reverse(n*n) == reverse(n)*reverse(n)
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter m: "); int m = sc.nextInt();
        System.out.print("Enter n: "); int n = sc.nextInt();

        if (m >= n) {
            System.out.println("INVALID INPUT.");
            return;
        }

        int freq = 0;
        System.out.println("THE PRIME-ADAM INTEGERS ARE:");
        for (int i = m; i <= n; i++) {
            if (isPrime(i) && isAdam(i)) {
                System.out.print(i + " ");
                freq++;
            }
        }
        if (freq == 0) System.out.print("NIL");
        System.out.println("\nFREQUENCY OF PRIME-ADAM INTEGERS IS: " + freq);
    }
}

