Algorithm:
1. Accept M and N; validate 0<M<10 and 2<N<6; if invalid print OUT OF RANGE.
2. Accept M×N matrix elements; validate each element is 0-7; if invalid print INVALID INPUT.
3. Display original matrix.
4. For each row, compute decimal = sum of (element[col] × 8^(N-1-col)) for col 0 to N-1.
5. Display decimal equivalent alongside each row.

Java Program:
import java.util.Scanner;
public class OctalMatrix {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter M: "); int M = sc.nextInt();
        System.out.print("Enter N: "); int N = sc.nextInt();

        if (M <= 0 || M >= 10 || N <= 2 || N >= 6) {
            System.out.println("OUT OF RANGE");
            return;
        }

        int[][] A = new int[M][N];
        boolean valid = true;

        for (int i = 0; i < M && valid; i++) {
            System.out.print("ENTER ELEMENTS FOR ROW " + (i+1) + ": ");
            for (int j = 0; j < N; j++) {
                A[i][j] = sc.nextInt();
                if (A[i][j] < 0 || A[i][j] > 7) {
                    valid = false;
                    break;
                }
            }
        }

        if (!valid) {
            System.out.println("INVALID INPUT");
            return;
        }

        System.out.println("FILLED MATRIX          DECIMAL EQUIVALENT");
        for (int i = 0; i < M; i++) {
            // Display row
            for (int j = 0; j < N; j++)
                System.out.print(A[i][j] + " ");

            // Calculate decimal equivalent
            long decimal = 0;
            long power = 1;
            for (int j = N-1; j >= 0; j--) {
                decimal += A[i][j] * power;
                power *= 8;
            }
            System.out.println("          " + decimal);
        }
    }
}
