Algorithm:
1. Accept sentence; check last character is '.', '?' or '!'; else print INVALID INPUT.
2. Remove last character; split by spaces into word array.
3. Sort: primary key = word length (ascending); secondary key = alphabetical order (for equal length).
4. Display original sentence and sorted words.

Java Program:
import java.util.Scanner;
public class WordSort {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter sentence: ");
        String sentence = sc.nextLine().trim();

        // Validate terminating character
        char last = sentence.charAt(sentence.length() - 1);
        if (last != '.' && last != '?' && last != '!') {
            System.out.println("INVALID INPUT");
            return;
        }

        // Remove terminator and split
        String body = sentence.substring(0, sentence.length() - 1);
        String[] words = body.split(" ");
        int n = words.length;

        // Sort by length, then alphabetically (bubble sort)
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - i - 1; j++) {
                boolean swap = false;
                if (words[j].length() > words[j+1].length()) {
                    swap = true;
                } else if (words[j].length() == words[j+1].length() &&
                           words[j].compareTo(words[j+1]) > 0) {
                    swap = true;
                }
                if (swap) {
                    String temp = words[j];
                    words[j] = words[j+1];
                    words[j+1] = temp;
                }
            }
        }

        // Display
        System.out.println(sentence);
        for (int i = 0; i < n; i++)
